<?php
require __DIR__.'/lib.php';require_login();require_once __DIR__.'/category_assignment.php';
if(current_user()['role']!=='Admin'){http_response_code(403);exit('Only Admin can assign all product categories.');}
if(!product_categories_ready()){header('Location: upgrade_v5.php');exit;}
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{verify_csrf();if(empty($_POST['review_ack']))throw new Exception('Review the assignments and tick the acknowledgment first.');$digest=$_POST['digest']??'';if(!is_string($digest)||!hash_equals($_SESSION['category_assignment_digest']??'', $digest)||$digest==='')throw new Exception('Reload the assignment preview.');$count=apply_category_assignments($digest);$success=$count.' product categories assigned. Existing valid assignments were preserved.';unset($_SESSION['category_assignment_digest']);}catch(Throwable $e){$error=$e->getMessage();}
}
$rows=db()->query('SELECT * FROM products ORDER BY id')->fetchAll();$plan=category_assignment_plan($rows);$digest=category_assignment_digest($rows);$_SESSION['category_assignment_digest']=$digest;$counts=[];$pending=0;$changes=0;
foreach($plan as $r){if(!$r['main'])$pending++;else $counts[$r['main']]=($counts[$r['main']]??0)+1;if($r['main']!==$r['old_main']||$r['sub']!==$r['old_sub'])$changes++;}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Assign Product Categories</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/typography.css?v=5.4.6-b"></head><body><main class="content"><div class="page-head"><div><h1>Assign Product Categories</h1><p>Review all product categories before applying them.</p></div><a class="btn ghost" href="index.php?page=products">Product Master</a></div>
<?php if($error):?><div class="alert danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?>
<div class="card"><p><b><?=count($plan)?> products · <?=$changes?> changes · <?=$pending?> need manual review</b></p><p>Only Main Category and Subcategory are updated. Valid manual assignments are kept. All changes are recorded in Activity Log.</p><div class="picker-filters"><?php foreach($counts as $m=>$n):?><span class="badge info"><?=e($m)?>: <?=$n?></span><?php endforeach;?></div>
<form method="post" data-confirm="Apply these category assignments to the entire product catalog?"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="digest" value="<?=e($digest)?>"><label class="ack"><input type="checkbox" name="review_ack" value="1" required>I reviewed the assignments below and backed up the database.</label><p><button class="btn primary" <?=($pending||!$changes)?'disabled':''?>>Apply Category Assignments</button></p></form></div>
<div class="card table-wrap"><table class="table"><thead><tr><th>SKU</th><th>Product</th><th>Previous tags</th><th>Main Category</th><th>Subcategory</th><th>Basis</th></tr></thead><tbody><?php foreach($plan as $r):?><tr><td class="mono"><?=e($r['sku'])?></td><td><?=e($r['name'])?></td><td><?=e(($r['old_main']?:'Unassigned').' / '.$r['old_sub'])?></td><td><?=e($r['main']?:'Needs review')?></td><td><?=e(in_array($r['main'],['Oils','Liquid Essentials'],true)?'No subcategory needed':($r['sub']?:'Needs review'))?></td><td><?=e($r['reason'])?></td></tr><?php endforeach;?></tbody></table></div></main><script src="assets/app.js"></script></body></html>
